export const MARKS=[{key:"computer",label:"Open the computer"},{key:"binoculars",label:"Look through the binoculars"}],COACHING={retireAfter:3,calmSeconds:30},OPENED={computer:1,binoculars:2,printer:4,wastebasket:8,lamp:16,cabinet:32,board:64,whiteboard:128,calendar:256,rolodex:512,notes:1024,today:2048,window:4096};export function openedCount(e){let r=0;for(let t=e>>>0;t;t&=t-1)r++;return r}export function noteOpened(e,r){return OPENED[r]?(e|OPENED[r])>>>0:e>>>0}export function marksShown(e,r=COACHING){return openedCount(e)>=r.retireAfter?[]:MARKS.filter(t=>!(e&OPENED[t.key])).map(t=>t.key)}
